  cases.append({'id':cid,'pair_id':f'li20-pair-{i:02d}','polarity':polarity,'axis':axis,'expected':{'v17_requested_relation':polarity=='positive','v30_relevant':polarity=='positive'},'rationale':rationale,'input':inp})
